# exec()'d by build-spec.py for wave2: defines W2 and WAVE2_SCOPE. {WD} = wave2 dir; wave-1 receipts live under {RD}/wave1/.
W2 = []

WAVE2_SCOPE = ("## WAVE 2 SCOPE (falsify wave; wave 1 has landed and is quiescent: read its receipts under {RD}/wave1/)\n"
               "Seats are READ-ONLY on the lane except these single-writer paths: {LANE}/corpus/instruments/capture-binding-check.py, capture-binding-fixtures/** and capture-binding-ledger.json: ExecCBFix (fixes only) | {LANE}/corpus/knowledge/program-scope-rules-and-asset-boundaries.md: ScribeEntryFix (fixes only) | {LANE}/corpus/QUALITY.md: ScribeQualityFix (append-only, fixes only) | {LANE}/corpus/lessons/round-32.md: ScribeLesson | {LANE}/SCORECARD.md: ScribeScorecard (append-only) | {LANE}/SHONEN.md: ScribeShonen | {LANE}/SKILL.md: ScribeSkillGate (append-only) | {LANE}/corpus/instruments/README.md: ScribeInstrReadme (append-only) | every {WD}/<YourName>.md receipt and your own named scratch dir under {WD}/. Everything else is read-only. Fixtures and mutants live in `mktemp -d` scratch copies of {LANE}/corpus (use `--root` where the instrument accepts it); never run an instrument in the lane in a way that writes (`resolve.py` writes citation-survival.* next to itself: scratch only).\n\n")

C1_FILES = "{LANE}/corpus/instruments/capture-binding-check.py, capture-binding-ledger.json, capture-binding-fixtures/, the round-23..32 manifests"

# ---- per-limb falsifiers (8 executors): independent re-derivation of each ledger row
LIMBS = [("CB-url-required", "missing `url` accepted"), ("CB-url-registry-equal", "`url` != registry URL accepted"),
         ("CB-url-scheme", "non-http(s) scheme accepted"), ("CB-utc-format", "malformed `fetched_utc` accepted"),
         ("CB-id-url-consistency", "one id with two urls across manifests accepted"),
         ("CB-live-absent", "live-absent counted as present"), ("CB-live-unreachable", "live-unreachable counted as present/confirmed"),
         ("CB-exit-on-unbound", "exit status ignores unbound records")]
for lid, desc in LIMBS:
    it(W2, "ExecLimb" + lid.replace("-", ""), "executor", """Falsify ledger limb `%s` (%s) of the C1 ledger on the LANDED bytes. Wave 1 landed the checker {LANE}/corpus/instruments/capture-binding-check.py and ledger {LANE}/corpus/instruments/capture-binding-ledger.json (read-only for you; all work in a mktemp scratch copy of {LANE}/corpus). (1) Re-derive by hand: copy {LANE}/corpus to a scratch dir, read the ledger row id `%s`, run its kill command on the UNMUTATED copy (record exit and whether `signal` matches), apply the row's find/replace yourself with python (assert find occurs exactly once; `python3 -m py_compile` the result), run the kill command again, and compare with the counter's `LIMB %s` line from `python3 corpus/instruments/limb-mutation-check.py --ledger corpus/instruments/capture-binding-ledger.json` (run it too). (2) Second mutant: invent a DIFFERENT one-line mutant of the same check (not the ledger's) and say whether the checker's controls or fixtures kill it; (3) say whether the limb is load-bearing only through one witnessing control/fixture (`weak`) or through more than one (`holds`), and name the control(s). A survivor is reported with the exact mutant, never relabelled. Write {WD}/ExecLimb%s.md with every command and output.""" % (lid, desc, lid, lid, lid.replace("-", "")))

# ---- checker mutants beyond the ledger (6 mutation-testers)
CMUT = [
    ("MutCBLastUrl", "registry URL parser takes the LAST http(s) token of the `source` cell instead of the first"),
    ("MutCBCountVsIn", "live-compare counts a quote present when `quote in text` on the RAW (un-normalized) live text, and 0 occurrences are not distinguished from partial"),
    ("MutCBHttpErrorPresent", "live-compare does not check the HTTP status, so an HTTP 404/500 error page body that happens to contain the quote text is treated as live-present (fetch helper swallows the status)"),
    ("MutCBUnrecordedNoNote", "an `unrecorded` fetched_utc is accepted without a `fetched_utc_note`"),
    ("MutCBControlTautology", "the L-controls compute `observed` by calling the same function that computes `expect` (a tautology), so every control prints ok=y whatever the checker does"),
    ("MutCBNondeterministic", "stdout depends on dict/set iteration order or the scratch temp path, so two runs are not byte-identical"),
]
for name, desc in CMUT:
    it(W2, name, "mutation-tester", """Checker mutant attack: in a scratch copy (mktemp; never edit {LANE}) of {LANE}/corpus/instruments/capture-binding-check.py apply this one mutation (adapt it to the real code): %s. Run the mutant offline (`python3 <mutant> --root <scratch lane copy containing corpus/>`), and through the ledger runner if it applies. The frozen C1 design (claims.json `mutants_of_the_checker`) requires each checker mutant to be caught by a CONTROL line or a ledger limb, i.e. to NOT print `records=R bound=R unbound=0`, `controls=8 as-expected=8` and exit 0 byte-identically to the real run. Report: the mutant diff, its full output and exit code, whether it is KILLED (output or exit differs from the real checker; name the control/limb) or a SURVIVOR (byte-identical or equally green), and for a survivor the smallest control or fixture that would kill it. If your mutant is not expressible in the real code, say so with the line you read. Write {WD}/%s.md.""" % (desc, name))

# ---- live observations over the real records (4 executors, network = observation, not a clause)
for k, sl in enumerate(["round-23 and round-24 manifests (23 records) first half: the first 12 in sorted manifest order",
                        "the remaining records of round-23/round-24 (11 records)",
                        "round-25, 26, 28, 29 manifests (all their records, 11)",
                        "round-30, 31 and 32 manifests (S041, S046, S047, S048, S049, S050)"]):
    it(W2, "ExecLive%d" % (k + 1), "executor", """Live observation (NOT a kill-rule clause; the network is not a committed byte). Run the landed checker's live mode on your slice - %s - from a scratch copy so nothing is written into the lane: `D=$(mktemp -d) && cp -r {LANE}/corpus "$D/" && python3 {LANE}/corpus/instruments/capture-binding-check.py --root "$D" --live --source <ID> [--source ...] --timeout 60` (instrument UA, public documentation URLs only, one request per record, never a retry storm; if a host returns 403/429, record `live-unreachable` with the code and stop for that host). Paste every `LIVE ...` line, the `live records=...` summary and the exit code. For every `live-absent` or `live-partial` record: classify with evidence (diff a fresh `capture-source.py` capture in scratch against the committed capture: page drift / host moved / the quote was a transient value / the capture was wrong) and state the consequence for the entry that cites that id (read its `used-by`) WITHOUT editing anything. Also record the instrument's answer for the localhost controls (offline run still `controls=8 as-expected=8`). Write {WD}/ExecLive%d.md with a table id | verdict | evidence.""" % (sl, k + 1))

